import java.util.*;

public class Solution {
    record Transferencia(String de, String para, long centavos) {}

    static class Splitwise {
        private record Posicao(String id, long valor) {}

        // maior valor primeiro; empate pelo menor id
        private static final Comparator<Posicao> PRIORIDADE =
                Comparator.comparingLong(Posicao::valor).reversed().thenComparing(Posicao::id);

        private final Set<String> usuarios = new HashSet<>();
        // grupo -> (membro -> saldo líquido em centavos). TreeMap mantém a saída ordenada por id.
        private final Map<String, TreeMap<String, Long>> grupos = new HashMap<>();

        void adicionarUsuario(String id) {
            if (id == null || id.isBlank()) throw new IllegalArgumentException("id obrigatorio");
            if (!usuarios.add(id)) throw new IllegalArgumentException("usuario duplicado: " + id);
        }

        void criarGrupo(String grupoId, List<String> membros) {
            if (grupoId == null || grupos.containsKey(grupoId)) throw new IllegalArgumentException("grupo invalido ou duplicado");
            if (membros == null || membros.isEmpty()) throw new IllegalArgumentException("grupo sem membros");
            TreeMap<String, Long> saldos = new TreeMap<>();
            for (String m : membros) {
                if (!usuarios.contains(m)) throw new IllegalArgumentException("usuario inexistente: " + m);
                saldos.put(m, 0L);
            }
            grupos.put(grupoId, saldos);
        }

        // O(n)
        void despesaIgual(String grupoId, String pagador, long total, List<String> participantes) {
            TreeMap<String, Long> saldos = grupo(grupoId);
            exigirMembro(saldos, pagador);
            exigirPositivo(total);
            if (participantes == null || participantes.isEmpty()) throw new IllegalArgumentException("sem participantes");
            if (new HashSet<>(participantes).size() != participantes.size()) throw new IllegalArgumentException("participante repetido");
            int n = participantes.size();
            long base = total / n, resto = total % n;
            Map<String, Long> partes = new LinkedHashMap<>();
            for (int i = 0; i < n; i++) partes.put(participantes.get(i), base + (i < resto ? 1 : 0));
            aplicar(saldos, pagador, total, partes);
        }

        void despesaExata(String grupoId, String pagador, Map<String, Long> partes) {
            TreeMap<String, Long> saldos = grupo(grupoId);
            exigirMembro(saldos, pagador);
            if (partes == null || partes.isEmpty()) throw new IllegalArgumentException("sem participantes");
            long total = 0;
            for (long v : partes.values()) {
                exigirPositivo(v);
                total = Math.addExact(total, v);
            }
            aplicar(saldos, pagador, total, partes);
        }

        void despesaPercentual(String grupoId, String pagador, long total, Map<String, Integer> percentuais) {
            TreeMap<String, Long> saldos = grupo(grupoId);
            exigirMembro(saldos, pagador);
            exigirPositivo(total);
            if (percentuais == null || percentuais.isEmpty()) throw new IllegalArgumentException("sem participantes");
            int soma = 0;
            for (int p : percentuais.values()) {
                if (p < 0) throw new IllegalArgumentException("percentual negativo");
                soma += p;
            }
            if (soma != 100) throw new IllegalArgumentException("percentuais devem somar 100, somam " + soma);
            Map<String, Long> partes = new TreeMap<>();
            long distribuido = 0;
            for (var e : new TreeMap<>(percentuais).entrySet()) {
                long parte = total * e.getValue() / 100;
                partes.put(e.getKey(), parte);
                distribuido += parte;
            }
            long resto = total - distribuido; // < número de participantes com p > 0
            for (var e : partes.entrySet()) {
                if (resto == 0) break;
                if (percentuais.get(e.getKey()) > 0) {
                    e.setValue(e.getValue() + 1);
                    resto--;
                }
            }
            aplicar(saldos, pagador, total, partes);
        }

        void pagar(String grupoId, String de, String para, long centavos) {
            TreeMap<String, Long> saldos = grupo(grupoId);
            exigirMembro(saldos, de);
            exigirMembro(saldos, para);
            if (de.equals(para)) throw new IllegalArgumentException("pagamento para si mesmo");
            exigirPositivo(centavos);
            saldos.merge(de, centavos, Long::sum);
            saldos.merge(para, -centavos, Long::sum);
        }

        Map<String, Long> saldos(String grupoId) {
            return Collections.unmodifiableMap(new TreeMap<>(grupo(grupoId)));
        }

        // O(n log n): cada iteração zera pelo menos um lado, então há no máximo n - 1 transferências.
        List<Transferencia> simplificar(String grupoId) {
            PriorityQueue<Posicao> credores = new PriorityQueue<>(PRIORIDADE);
            PriorityQueue<Posicao> devedores = new PriorityQueue<>(PRIORIDADE);
            for (var e : grupo(grupoId).entrySet()) {
                if (e.getValue() > 0) credores.add(new Posicao(e.getKey(), e.getValue()));
                else if (e.getValue() < 0) devedores.add(new Posicao(e.getKey(), -e.getValue()));
            }
            List<Transferencia> resultado = new ArrayList<>();
            while (!credores.isEmpty() && !devedores.isEmpty()) {
                Posicao c = credores.poll(), d = devedores.poll();
                long valor = Math.min(c.valor(), d.valor());
                resultado.add(new Transferencia(d.id(), c.id(), valor));
                if (c.valor() > valor) credores.add(new Posicao(c.id(), c.valor() - valor));
                if (d.valor() > valor) devedores.add(new Posicao(d.id(), d.valor() - valor));
            }
            return resultado;
        }

        private void aplicar(TreeMap<String, Long> saldos, String pagador, long total, Map<String, Long> partes) {
            for (String p : partes.keySet()) exigirMembro(saldos, p); // valida tudo antes de mutar
            saldos.merge(pagador, total, Long::sum);
            for (var e : partes.entrySet()) saldos.merge(e.getKey(), -e.getValue(), Long::sum);
        }

        private TreeMap<String, Long> grupo(String grupoId) {
            TreeMap<String, Long> g = grupos.get(grupoId);
            if (g == null) throw new IllegalArgumentException("grupo inexistente: " + grupoId);
            return g;
        }

        private static void exigirMembro(Map<String, Long> saldos, String id) {
            if (!saldos.containsKey(id)) throw new IllegalArgumentException("nao eh membro do grupo: " + id);
        }

        private static void exigirPositivo(long v) {
            if (v <= 0) throw new IllegalArgumentException("valor deve ser positivo");
        }
    }
}

