import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

class SolutionTest {
    Solution.Splitwise s;

    @BeforeEach void setup() {
        s = new Solution.Splitwise();
        for (String u : List.of("ana", "bia", "caio", "duda")) s.adicionarUsuario(u);
        s.criarGrupo("viagem", List.of("ana", "bia", "caio"));
    }

    static Solution.Transferencia t(String de, String para, long c) {
        return new Solution.Transferencia(de, para, c);
    }

    @Test void divisaoIgualComCentavoQueSobra() {
        s.despesaIgual("viagem", "ana", 1_000, List.of("ana", "bia", "caio"));
        assertEquals(Map.of("ana", 666L, "bia", -333L, "caio", -333L), s.saldos("viagem"));
    }

    @Test void restoVaiParaOsPrimeirosDaLista() {
        s.despesaIgual("viagem", "ana", 1_001, List.of("caio", "bia"));
        // caio 501, bia 500
        assertEquals(Map.of("ana", 1_001L, "bia", -500L, "caio", -501L), s.saldos("viagem"));
    }

    @Test void saldosIncluemMembrosZeradosEmOrdem() {
        var saldos = s.saldos("viagem");
        assertEquals(List.of("ana", "bia", "caio"), new ArrayList<>(saldos.keySet()));
        assertEquals(0L, saldos.get("bia"));
    }

    @Test void despesaExata() {
        s.despesaExata("viagem", "bia", Map.of("ana", 700L, "caio", 300L));
        assertEquals(Map.of("ana", -700L, "bia", 1_000L, "caio", -300L), s.saldos("viagem"));
    }

    @Test void despesaPercentualComArredondamento() {
        s.despesaPercentual("viagem", "caio", 1_001, Map.of("caio", 20, "bia", 30, "ana", 50));
        // floors: ana 500, bia 300, caio 200 = 1000; sobra 1 centavo -> ana (ordem alfabética)
        assertEquals(Map.of("ana", -501L, "bia", -300L, "caio", 801L), s.saldos("viagem"));
    }

    @Test void percentualZeroNaoRecebeCentavoDoResto() {
        s.despesaPercentual("viagem", "caio", 101, Map.of("ana", 0, "bia", 50, "caio", 50));
        // bia 50 + 1, caio 50
        assertEquals(Map.of("ana", 0L, "bia", -51L, "caio", 51L), s.saldos("viagem"));
    }

    @Test void somaDosSaldosEhSempreZero() {
        s.despesaIgual("viagem", "ana", 9_999, List.of("ana", "bia", "caio"));
        s.despesaPercentual("viagem", "bia", 777, Map.of("ana", 33, "bia", 33, "caio", 34));
        s.despesaExata("viagem", "caio", Map.of("ana", 123L));
        s.pagar("viagem", "bia", "ana", 50);
        assertEquals(0L, s.saldos("viagem").values().stream().mapToLong(Long::longValue).sum());
    }

    @Test void pagarAcertaSaldo() {
        s.despesaIgual("viagem", "ana", 900, List.of("ana", "bia", "caio"));
        s.pagar("viagem", "bia", "ana", 300);
        s.pagar("viagem", "caio", "ana", 300);
        assertEquals(Map.of("ana", 0L, "bia", 0L, "caio", 0L), s.saldos("viagem"));
        assertEquals(List.of(), s.simplificar("viagem"));
    }

    @Test void simplificarMaiorDevedorPagaMaiorCredor() {
        s.despesaIgual("viagem", "ana", 3_000, List.of("ana", "bia", "caio"));
        s.despesaIgual("viagem", "bia", 600, List.of("bia", "caio"));
        // ana +2000, bia -700, caio -1300
        assertEquals(List.of(t("caio", "ana", 1_300), t("bia", "ana", 700)), s.simplificar("viagem"));
    }

    @Test void simplificarEliminaIntermediario() {
        s.despesaExata("viagem", "bia", Map.of("ana", 100L)); // ana deve 100 a bia
        s.despesaExata("viagem", "caio", Map.of("bia", 100L)); // bia deve 100 a caio
        assertEquals(List.of(t("ana", "caio", 100)), s.simplificar("viagem"));
    }

    @Test void simplificarNaoAlteraSaldos() {
        s.despesaIgual("viagem", "ana", 300, List.of("ana", "bia", "caio"));
        var antes = s.saldos("viagem");
        s.simplificar("viagem");
        assertEquals(antes, s.saldos("viagem"));
    }

    @Test void simplificarZeraTudoComNoMaximoNMenosUm() {
        s.criarGrupo("rep", List.of("ana", "bia", "caio", "duda"));
        s.despesaIgual("rep", "ana", 12_345, List.of("ana", "bia", "caio", "duda"));
        s.despesaIgual("rep", "bia", 7_001, List.of("caio", "duda"));
        s.despesaPercentual("rep", "duda", 5_000, Map.of("ana", 10, "bia", 20, "caio", 70));
        var saldos = new HashMap<>(s.saldos("rep"));
        var transferencias = s.simplificar("rep");
        assertTrue(transferencias.size() <= 3);
        for (var tr : transferencias) {
            assertTrue(tr.centavos() > 0);
            saldos.merge(tr.de(), tr.centavos(), Long::sum);
            saldos.merge(tr.para(), -tr.centavos(), Long::sum);
        }
        saldos.values().forEach(v -> assertEquals(0L, v));
    }

    @Test void erros() {
        assertThrows(IllegalArgumentException.class, () -> s.adicionarUsuario("ana"));
        assertThrows(IllegalArgumentException.class, () -> s.criarGrupo("viagem", List.of("ana")));
        assertThrows(IllegalArgumentException.class, () -> s.criarGrupo("x", List.of("ze")));
        assertThrows(IllegalArgumentException.class, () -> s.saldos("nada"));
        assertThrows(IllegalArgumentException.class, () -> s.despesaIgual("viagem", "duda", 100, List.of("ana")));
        assertThrows(IllegalArgumentException.class, () -> s.despesaIgual("viagem", "ana", 100, List.of("duda")));
        assertThrows(IllegalArgumentException.class, () -> s.despesaIgual("viagem", "ana", 0, List.of("bia")));
        assertThrows(IllegalArgumentException.class, () -> s.despesaIgual("viagem", "ana", 100, List.of("bia", "bia")));
        assertThrows(IllegalArgumentException.class, () -> s.despesaIgual("viagem", "ana", 100, List.of()));
        assertThrows(IllegalArgumentException.class, () -> s.despesaExata("viagem", "ana", Map.of("bia", 0L)));
        assertThrows(IllegalArgumentException.class, () -> s.despesaPercentual("viagem", "ana", 100, Map.of("bia", 60, "caio", 30)));
        assertThrows(IllegalArgumentException.class, () -> s.despesaPercentual("viagem", "ana", 100, Map.of("bia", 110, "caio", -10)));
        assertThrows(IllegalArgumentException.class, () -> s.pagar("viagem", "ana", "ana", 10));
    }

    @Test void erroNaoDeixaDespesaPelaMetade() {
        assertThrows(IllegalArgumentException.class,
                () -> s.despesaIgual("viagem", "ana", 300, List.of("bia", "duda")));
        assertEquals(Map.of("ana", 0L, "bia", 0L, "caio", 0L), s.saldos("viagem"));
    }
}
